package vaultor.linked;
import java.nio.file.*;import java.util.*;

public final class LinkedRetentionTests extends SafetyTests {
    public static void main(String[] args)throws Exception {
        check("acknowledgement still verifies earlier records before writing its receipt",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){
            var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Local"),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));
            Path op=f.journal.resolve(saved.operation());Files.write(op.resolve("00.rec"),new byte[]{1,2,3});rejects("CORRUPT",()->f.store.acknowledgeLinkedSave(OWNER,saved.operation()));
            require(!Files.exists(op.resolve("08.rec")));require(Files.readString(f.file).equals("Local"));require(Files.readString(op.resolve("captured.md")).equals("Base"));
        }});
        check("a valid checksum with a foreign earlier scope cannot acknowledge a committed receipt",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){
            var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Local"),UUID.randomUUID().toString());Path op=f.journal.resolve(saved.operation()),file=op.resolve("00.rec");var r=Journal.decode(Files.readAllBytes(file));
            Files.write(file,Journal.encode(new Journal.Record(r.operation(),"another-workspace",r.generation(),r.rootIdentity(),r.relative(),r.epoch(),r.version(),r.state(),r.baseRevision(),r.base(),r.local(),r.visual())));
            rejects("CORRUPT",()->f.store.acknowledgeLinkedSave(OWNER,saved.operation()));require(!Files.exists(op.resolve("08.rec")));require(Files.readString(f.file).equals("Local"));
        }});
        check("150 acknowledged checkpoints coalesce only older drafts and retain latest rejected V plus validated L",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");for(int i=1;i<=150;i++)require(candidate(f.store,doc,i,"Draft "+i)!=null);f.store.journalDraft(OWNER,doc.document(),doc.epoch(),151,"Rejected current visual draft",null,null);var recovered=f.store.recover(OWNER);require(recovered.size()==1);require(recovered.getFirst().record().visual().equals("Rejected current visual draft"));require(Arrays.equals(recovered.getFirst().record().local(),LinkedStore.utf8("Draft 150")));require(Files.readString(f.file).equals("Base"));}});
        check("only acknowledged successful saves enter bounded twenty-version history",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){for(int i=0;i<30;i++){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Revision "+i),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));f.store.acknowledgeLinkedSave(OWNER,saved.operation());if(i<29)Files.setLastModifiedTime(f.journal.resolve(saved.operation()).resolve("08.rec"),java.nio.file.attribute.FileTime.fromMillis(System.currentTimeMillis()+86400000));f.store.closeDocument(OWNER,doc.document());}var recovered=f.store.recover(OWNER);require(recovered.size()==20);require(recovered.stream().allMatch(r->r.record()!=null&&r.record().state().equals("LINKED_ACKNOWLEDGED")));require(Files.readString(f.file).equals("Revision 29"));require(recovered.stream().anyMatch(r->Arrays.equals(r.record().local(),LinkedStore.utf8("Revision 29"))));}});
        check("unacknowledged completed Save and uncertain conflict are never history-pruned",()->{final Path[] conflictPath={null};try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",(phase,op)->{if(phase.equals("replacement-before-publish")&&Journal.decode(Files.readAllBytes(op.resolve("00.rec"))).relative().equals("conflict.md"))require(external("create",conflictPath[0],"External occupant")==0);})){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var unacknowledged=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Unacknowledged saved source"),UUID.randomUUID().toString());require(unacknowledged.state().equals("COMMITTED"));conflictPath[0]=f.root.resolve("conflict.md");Files.writeString(conflictPath[0],"Conflict base");var conflict=f.store.openLinked(OWNER,f.rootCap,"conflict.md");var uncertain=f.store.saveLinked(OWNER,conflict.document(),conflict.epoch(),candidate(f.store,conflict,1,"Conflict local"),UUID.randomUUID().toString());require(uncertain.state().equals("RECOVERY_REQUIRED"));Files.writeString(f.root.resolve("other.md"),"Other");for(int i=0;i<25;i++){var other=f.store.openLinked(OWNER,f.rootCap,"other.md");var saved=f.store.saveLinked(OWNER,other.document(),other.epoch(),candidate(f.store,other,1,"Other "+i),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));f.store.acknowledgeLinkedSave(OWNER,saved.operation());f.store.closeDocument(OWNER,other.document());}require(f.store.recover(OWNER).stream().anyMatch(r->r.operation().equals(unacknowledged.operation())&&r.record().state().startsWith("LINKED_COMMITTED:")));require(f.store.recover(OWNER).stream().anyMatch(r->r.operation().equals(uncertain.operation())&&r.record().state().startsWith("REPLACEMENT_UNCERTAIN:")));require(Files.readString(f.journal.resolve(unacknowledged.operation()).resolve("captured.md")).equals("Base"));require(Files.readString(conflictPath[0]).equals("External occupant"));}});
        check("large acknowledged history stays within64MiB while new saves continue",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){
            String body="x".repeat(250000);for(int i=0;i<24;i++){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,body+i),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));f.store.acknowledgeLinkedSave(OWNER,saved.operation());f.store.closeDocument(OWNER,doc.document());}
            var recovered=f.store.recover(OWNER);require(recovered.size()<20);long bytes=0;for(var recovery:recovered)try(var files=Files.list(f.journal.resolve(recovery.operation()))){for(Path file:files.toList())bytes+=Files.size(file);}require(bytes<=64L*1024*1024);require(Files.readString(f.file).equals(body+23));
        }});
        Files.writeString(Path.of("native/linked-markdown/evidence/production/retention-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
